typedef unsigned int u32;
#define R(a) (*(volatile u32 *)(a))
#define OUT ((volatile u32 *)0x01C00000)
#define VEC ((volatile u32 *)0x01C7FE00)
#define ICFG00 R(0x01EEF100)
#define T0CON R(0x00010400)
#define T0CNT R(0x00010404)
#define T0PRD R(0x00010408)
#define T4CON R(0x00010800)
#define T4CNT R(0x00010804)
static volatile u32 n, last, minp = 0xffffffffu, maxp, sp_in, ssp0, icfg0, icfg1, entry0;
__attribute__((interrupt(""))) void t0_isr(void)
{
    u32 now = T4CNT, sp;
