p='firmware/src/sb.h'; s=open(p).read()
old=''' * from older records' images. The tick handler updates the heartbeat
 * between two increments of seq, so a capture whose seq is even shows a
 * consistent heartbeat. */'''
new=''' * from older records' images. fwtest can take a capture in the middle of
 * the tick handler (docs/HARNESS.md, "Time"), so the handler writes the
 * heartbeat twice, first (beats, ticks) then (beats_b, ticks_b), between
 * two increments of seq: a capture can split at most one copy, so at
 * least one is always consistent, and both are when seq is even. */'''
assert old in s; s=s.replace(old,new)
old='''    u32 seq;      /* odd while the tick handler is updating the words above */
'''
new='''    u32 seq;      /* odd while the tick handler is updating the heartbeat */
    u32 beats_b;  /* the second copy of beats and ticks, written after them */
    u32 ticks_b;
'''
assert old in s; s=s.replace(old,new); open(p,'w').write(s)
p='firmware/src/main.c'; s=open(p).read()
old='''    tb_last = now;
    sb_beacon.tick_count = n + 1;
    /* Every whole millisecond that has passed, so a late tick still leaves
     * the right count. Unsigned differences stay right across a wrap. */
    while (now - tb_done >= TICKS_PER_MS) {
        tb_done += TICKS_PER_MS;
        sb_beacon.beats++;
#if defined(SB_PROBE_SLOW)
        sb_probe_slow();
#endif
    }
    sb_beacon.ticks = now;
    sb_beacon.seq++;
'''
new='''    tb_last = now;
    sb_beacon.tick_count = n + 1;
    /* Every whole millisecond that has passed, so a late tick still leaves
     * the right count. Unsigned differences stay right across a wrap. */
    beats = sb_beacon.beats;
    while (now - tb_done >= TICKS_PER_MS) {
        tb_done += TICKS_PER_MS;
        beats++;
#if defined(SB_PROBE_SLOW)
        sb_probe_slow();
#endif
    }
    sb_beacon.beats = beats;
    sb_beacon.ticks = now;
    sb_beacon.beats_b = beats;
    sb_beacon.ticks_b = now;
    sb_beacon.seq++;
'''
assert old in s; s=s.replace(old,new)
s=s.replace('''    u32 now = JL_TIMER4->CNT - tb_start;
    u32 n = sb_beacon.tick_count;
''','''    u32 now = JL_TIMER4->CNT - tb_start;
    u32 n = sb_beacon.tick_count, beats;
''')
open(p,'w').write(s)
EOF
sh tools/build.sh build --out out/b1 2>&1 | grep -E '^(code|bss) ' ; cp out/b1/app.bin out/fw/m1.bin; rm -rf out/exp/r2; tools/fwtest run out/fw/m1.bin --ms 1000 --out out/exp/r2 --ram 0x01c00000:0x3c@end --ram 0x01c00000:0x3c@1 --ram 0x01c00000:0x3c@10 --ram 0x01c00000:0x3c@100 --ram 0x01c00000:0x3c@500 >/dev/null; python3 - <<'EOF'
import struct,glob,json
r=json.load(open('out/exp/r2/result.json'))['run']; print(r['emulated_ms'],r['instructions'])
names=['marker','beats','ticks','period','seq','beats_b','ticks_b','tick_count','imin','imax','wakes','clock','hr','hs','ht']
for f in sorted(glob.glob('out/exp/r2/ram-*')):
    v=dict(zip(names,struct.unpack('<15I',open(f,'rb').read())))
    a=v['beats']==v['ticks']//24000; b=v['beats_b']==v['ticks_b']//24000
    print(f.split('-')[-1], 'seq',v['seq'],'A ok' if a else 'A split','B ok' if b else 'B split', v['beats'],v['ticks'],v['beats_b'],v['ticks_b'],v['tick_count'],v['wakes'])
EOF

